c=sqlite3.connect('/var/lib/rollout/records.sqlite3')
for row in c.execute(\"SELECT name,sql FROM sqlite_master WHERE type='table'\"):
    print(row)
print('---ROWS---')
try:
    for row in c.execute('SELECT * FROM records LIMIT 5'):
        print(row)
except Exception as e:
    print('err',e)
print('---COUNT---')
try:
    print(c.execute('SELECT COUNT(*) FROM records').fetchone())
except Exception as e:
    print('err',e)
"

